<div class="hero"><div><div class="eyebrow">MONTHLY CONTROL ROOM</div><h1>Production & material pulse</h1><p>Track stock, receipts, issues, output, rejection, transfers and samples.</p></div><form class="month-form"><input type="month" name="month" value="<?= esc($month) ?>"><button class="primary">Apply</button></form></div><div class="stats"><?php $cards=[['Materials',count($rows)],['Receipts',$tot['receipts']],['Issued',$tot['issued']],['Production',$tot['production']],['Rejections',$tot['rejection']],['Samples',$tot['samples']]];foreach($cards as $c): ?><div class="stat"><span><?= esc($c[0]) ?></span><b><?= number_format((float)$c[1],2) ?></b></div><?php endforeach; ?></div><section class="panel"><div class="panel-title"><h3>Material snapshot</h3><p>Calculated closing = opening + receipts − issued.</p></div><div class="table-wrap"><table><thead><tr><th>Material</th><th>Opening</th><th>Receipt</th><th>Issued</th><th>Closing</th><th>Physical</th><th>Difference</th><th>Production</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= esc($r['code']) ?></b><small><?= esc($r['description']) ?></small></td><td><?= number_format($r['opening_stock'],3) ?></td><td><?= number_format($r['receipts'],3) ?></td><td><?= number_format($r['issued'],3) ?></td><td><b><?= number_format($r['closing_stock'],3) ?></b></td><td><?= $r['physical_stock_month_end']===null?'—':number_format($r['physical_stock_month_end'],3) ?></td><td><?= $r['physical_stock_month_end']===null?'—':number_format($r['closing_stock']-$r['physical_stock_month_end'],3) ?></td><td><?= number_format($r['production'],3) ?></td></tr><?php endforeach; ?></tbody></table></div></section>